-- Fantasy-league app database (fictional data). Generated by generate_fantasy.py.
DROP TABLE IF EXISTS fantasy_picks;
DROP TABLE IF EXISTS fantasy_managers;
DROP TABLE IF EXISTS driver_prices;

CREATE TABLE fantasy_managers (
  manager_id INT PRIMARY KEY,
  manager_name VARCHAR(60) NOT NULL,
  team_name VARCHAR(80) NOT NULL,
  country VARCHAR(40),
  joined_on DATE
);
CREATE TABLE driver_prices (
  season INT NOT NULL,
  driver_id VARCHAR(40) NOT NULL,
  price_musd NUMERIC(5,1) NOT NULL,
  PRIMARY KEY (season, driver_id)
);
CREATE TABLE fantasy_picks (
  manager_id INT REFERENCES fantasy_managers(manager_id),
  season INT NOT NULL,
  driver_id VARCHAR(40) NOT NULL,
  is_captain BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (manager_id, season, driver_id)
);



